// public/moments/index.json: the list of moment files the game loads at runtime. Generated by
// scripts/build_manifest.ts (npm run manifest) from the files in public/moments.

export interface ManifestEntry {
  /** stable id = file name without .json */
  id: string
  match: string
  /** match minute, for display / sorting */
  minute: number
  /** size of <id>.json in bytes */
  size: number
  /** <id>.play.json (replay data) exists */
  play: boolean
}

export interface Manifest {
  schema_version: 1
  count: number
  moments: ManifestEntry[]
}

/** Where the moment files live, relative to the page. */
export const MOMENTS_DIR = './moments'
